-- All synthetic users, prices and mutations are rolled back.
BEGIN;
CREATE FUNCTION pg_temp.shop_assert(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'SHOP_TEST_FAILED: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
CREATE FUNCTION pg_temp.shop_reject(statement text,expected text,label text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 BEGIN EXECUTE statement;
 EXCEPTION WHEN OTHERS THEN IF SQLSTATE=expected THEN RAISE NOTICE 'PASS: %',label; RETURN; ELSE RAISE; END IF; END;
 RAISE EXCEPTION 'SHOP_TEST_FAILED: accepted %',label;
END $$;
INSERT INTO auth.users(id,email) VALUES('91000000-0000-4000-8000-000000000001','shop-admin@example.invalid'),('91000000-0000-4000-8000-000000000002','shop-client@example.invalid');
INSERT INTO public.profiles(user_id,account_status) VALUES('91000000-0000-4000-8000-000000000001','active'),('91000000-0000-4000-8000-000000000002','active');
INSERT INTO public.user_roles(user_id,role) VALUES('91000000-0000-4000-8000-000000000001','admin');
SELECT pg_temp.shop_assert(NOT has_function_privilege('anon','public.admin_save_shop_service(jsonb,uuid,integer,uuid)','EXECUTE'),'anonymous service write denied');
SELECT pg_temp.shop_assert(NOT has_function_privilege('anon','public.admin_shop_preview(jsonb)','EXECUTE'),'anonymous admin simulation denied');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000002',true);
SELECT pg_temp.shop_reject($q$SELECT public.admin_save_shop_service('{}')$q$,'42501','client service mutation denied');
SELECT pg_temp.shop_reject($q$SELECT public.admin_shop_preview('{}')$q$,'42501','client cannot inspect provider fees');
SELECT pg_temp.shop_reject($q$UPDATE public.services SET icon_key='home'$q$,'42501','direct service writes denied');
SELECT set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000001',true);
DO $$
DECLARE payload jsonb; a public.services; b public.services; pack public.services; saved public.services; changed public.services;
 cart jsonb; preview jsonb; original jsonb; rate jsonb; task jsonb; opt jsonb; fee_row jsonb; req uuid:='91000000-0000-4000-8000-000000000003';
BEGIN
 payload:='{"slug":"shop-test-room","name_fr":"Chambre test","name_en":"Test bedroom","description_fr":"Test","description_en":"Test","shop_enabled":true,"icon_key":"bed","unit":"item","included_fr":"Test","included_en":"Test","change_reason":"Synthetic service"}';
 a:=public.admin_save_shop_service(payload,p_request_id=>req);
 PERFORM pg_temp.shop_assert(a.status='draft' AND a.icon_key='bed','new service remains draft and stores icon');
 saved:=public.admin_save_shop_service(payload,p_request_id=>req);
 PERFORM pg_temp.shop_assert(saved.id=a.id AND saved.version=a.version,'service creation retry is idempotent');
 PERFORM pg_temp.shop_reject(format('SELECT public.admin_save_shop_service(%L,NULL,NULL,%L)',(payload||'{"icon_key":"home"}')::text,req),'23505','retry with changed payload rejected');
 PERFORM pg_temp.shop_reject(format('SELECT public.admin_save_shop_service(%L)',(payload||'{"icon_key":"<script>"}')::text),'23514','untrusted icon rejected by database');
 PERFORM pg_temp.shop_reject(format('SELECT public.admin_save_shop_service(%L)',(payload||'{"quantity_step":0.0001}')::text),'22023','quantity precision is not silently rounded');
 a:=public.admin_save_shop_service('{"status":"published","change_reason":"Publish test"}',a.id,a.version);
 PERFORM pg_temp.shop_assert(a.status='published' AND a.version=2,'partial service update preserves content and increments version');
 PERFORM pg_temp.shop_reject(format('SELECT public.admin_save_shop_service(''{"status":"archived","change_reason":"Stale test"}'',%L,1)',a.id),'40001','stale service update rejected');
 b:=public.admin_save_shop_service(payload||'{"slug":"shop-test-kitchen","name_fr":"Cuisine test","name_en":"Test kitchen","icon_key":"kitchen","status":"published"}');
 pack:=public.admin_save_shop_service(payload||jsonb_build_object('slug','shop-test-package','offer_kind','bundle','icon_key','package','status','published','bundle_items',jsonb_build_array(jsonb_build_object('service_id',a.id,'quantity',2),jsonb_build_object('service_id',b.id,'quantity',1))));
 PERFORM pg_temp.shop_assert(pack.offer_kind='bundle' AND jsonb_array_length(pack.bundle_items)=2,'flat bundle and included quantities saved');
 PERFORM pg_temp.shop_reject(format('SELECT public.admin_save_shop_service(%L)',(payload||jsonb_build_object('slug','nested-test','offer_kind','bundle','bundle_items',jsonb_build_array(jsonb_build_object('service_id',pack.id,'quantity',1))))::text),'22023','nested packages refused');
 PERFORM pg_temp.shop_assert(EXISTS(SELECT 1 FROM jsonb_array_elements(public.shop_catalog()) x WHERE x->>'id'=a.id::text AND x->>'icon_key'='bed'),'public catalogue has service icon');
 cart:=jsonb_build_object('currency','CAD','items',jsonb_build_array(jsonb_build_object('service_id',a.id,'quantity',3),jsonb_build_object('service_id',b.id,'quantity',1)));
 preview:=public.admin_shop_preview(cart);
 PERFORM pg_temp.shop_assert(preview->'issues' ? 'RATE_UNCONFIGURED' AND preview->'subtotal_minor'='null'::jsonb,'missing prices never become zero');
 payload:=jsonb_build_object('service_id',a.id,'name_fr','Test','name_en','Test','pricing_mode','fixed','unit','item','currency','CAD','amount_minor',1001,'status','active');
 rate:=public.admin_save_billing('catalog_rates',payload,p_reason=>'Synthetic rate');
 PERFORM public.admin_save_billing('catalog_rates',payload||jsonb_build_object('service_id',b.id,'amount_minor',2000),p_reason=>'Synthetic kitchen rate');
 PERFORM public.admin_save_billing('catalog_rates',payload||jsonb_build_object('service_id',pack.id,'amount_minor',5000),p_reason=>'Synthetic package rate');
 payload:='{"name_fr":"Test","name_en":"Test","description_fr":"Test","description_en":"Test","payer":"client","basis":"service_subtotal_excluding_tax","fee_mode":"combined","fixed_minor":100,"percentage_bps":250,"currency":"CAD","status":"active"}';
 PERFORM public.admin_save_billing('platform_fee_rules',payload,p_reason=>'Synthetic global client fee');
 PERFORM public.admin_save_billing('platform_fee_rules',payload||'{"payer":"provider","fee_mode":"fixed","fixed_minor":0,"percentage_bps":null}',p_reason=>'Explicit zero provider fee');
 preview:=public.admin_shop_preview(cart||'{"subtotal_minor":1}');
 PERFORM pg_temp.shop_assert((preview->>'subtotal_minor')::bigint=5003 AND (preview->>'client_total_before_tax_minor')::bigint=5228,'quantities priced server-side, global fee fixed part counted once');
 PERFORM pg_temp.shop_assert(jsonb_array_length(preview->'fees')=2 AND (preview->'fees'->0->>'basis_minor')::bigint=5003,'fee basis aggregates both services');
 PERFORM pg_temp.shop_assert((preview->>'pricing_complete')::boolean AND NOT (preview->>'bookable')::boolean AND preview->>'taxes_status'='unconfigured','simulation stays non-bookable before taxes');
 original:=preview;
 preview:=public.admin_shop_preview(jsonb_build_object('currency','CAD','items',jsonb_build_array(jsonb_build_object('service_id',pack.id,'quantity',1),jsonb_build_object('service_id',a.id,'quantity',1))));
 PERFORM pg_temp.shop_assert(preview->'issues' ? 'SERVICE_ALREADY_INCLUDED' AND NOT (preview->>'pricing_complete')::boolean,'package plus included individual service cannot double bill');
 preview:=public.admin_shop_preview(jsonb_build_object('currency','CAD','items',jsonb_build_array(jsonb_build_object('service_id',pack.id,'quantity',2))));
 PERFORM pg_temp.shop_assert((preview->>'subtotal_minor')::bigint=10000 AND jsonb_array_length(preview->'items'->0->'bundle_members')=2,'package quantity priced without charging member prices');
 PERFORM pg_temp.shop_reject(format('SELECT public.admin_shop_preview(%L)',(cart||jsonb_build_object('items',jsonb_build_array(jsonb_build_object('service_id',a.id,'quantity',1.5))))::text),'22023','service quantity step enforced');
 preview:=public.admin_shop_preview(jsonb_build_object('currency','CAD','items',jsonb_build_array(jsonb_build_object('service_id',a.id,'quantity',1,'expected_version',1))));
 PERFORM pg_temp.shop_assert(preview->'issues' ? 'SERVICE_CHANGED','changed service version is reported');
 task:=public.admin_save_billing('catalog_components',jsonb_build_object('service_id',a.id,'slug','floor','kind','task','name_fr','Test','name_en','Test','description_fr','Test','description_en','Test','status','active'),p_reason=>'Synthetic task');
 opt:=public.admin_save_billing('catalog_components',jsonb_build_object('service_id',a.id,'slug','extra','kind','option','unit','item','name_fr','Test','name_en','Test','description_fr','Test','description_en','Test','status','active'),p_reason=>'Synthetic option');
 PERFORM public.admin_save_billing('catalog_rates',jsonb_build_object('service_id',a.id,'component_id',opt->>'id','name_fr','Test','name_en','Test','pricing_mode','unit','unit','item','currency','CAD','amount_minor',500,'status','active'),p_reason=>'Synthetic option rate');
 a:=public.admin_save_shop_service(jsonb_build_object('included_task_ids',jsonb_build_array(task->>'id'),'change_reason','Synthetic included task'),a.id,a.version);
 PERFORM public.admin_save_billing('catalog_links',jsonb_build_object('service_id',a.id,'parent_id',opt->>'id','child_id',task->>'id','relation','included','status','active'),p_reason=>'Synthetic task link');
 preview:=public.admin_shop_preview(jsonb_build_object('currency','CAD','items',jsonb_build_array(jsonb_build_object('service_id',a.id,'quantity',1,'options',jsonb_build_array(jsonb_build_object('component_id',opt->>'id','quantity',1))))));
 PERFORM pg_temp.shop_assert(preview->'issues' ? 'TASK_ALREADY_INCLUDED','option repeating an included task blocked');
 PERFORM pg_temp.shop_reject(format('SELECT public.admin_shop_preview(%L)',jsonb_build_object('currency','CAD','items',jsonb_build_array(jsonb_build_object('service_id',b.id,'quantity',1,'options',jsonb_build_array(jsonb_build_object('component_id',opt->>'id','quantity',1)))))::text),'22023','options cannot cross service scope');
 FOR fee_row IN SELECT to_jsonb(f) FROM public.platform_fee_rules f WHERE f.status='active' LOOP
  PERFORM public.admin_save_billing('platform_fee_rules','{"status":"archived"}',(fee_row->>'id')::uuid,(fee_row->>'version')::integer,'Switch to scoped test fees');
 END LOOP;
 payload:='{"name_fr":"Test","name_en":"Test","description_fr":"Test","description_en":"Test","payer":"client","basis":"service_subtotal_excluding_tax","fee_mode":"fixed","fixed_minor":10,"currency":"CAD","status":"active"}';
 PERFORM public.admin_save_billing('platform_fee_rules',payload||jsonb_build_object('service_id',a.id),p_reason=>'Scoped test fee');
 PERFORM public.admin_save_billing('platform_fee_rules',payload||jsonb_build_object('service_id',b.id,'fixed_minor',20),p_reason=>'Scoped test fee');
 PERFORM public.admin_save_billing('platform_fee_rules',payload||jsonb_build_object('service_id',a.id,'payer','provider','fixed_minor',0),p_reason=>'Explicit zero scoped fee');
 PERFORM public.admin_save_billing('platform_fee_rules',payload||jsonb_build_object('service_id',b.id,'payer','provider','fixed_minor',0),p_reason=>'Explicit zero scoped fee');
 preview:=public.admin_shop_preview(cart);
 PERFORM pg_temp.shop_assert((preview->>'client_total_before_tax_minor')::bigint=5033 AND jsonb_array_length(preview->'fees')=4,'service-scoped fees each apply once, not per quantity');
 rate:=public.admin_save_billing('catalog_rates','{"pricing_mode":"quote","amount_minor":null}',(rate->>'id')::uuid,(rate->>'version')::integer,'Synthetic quote mode');
 preview:=public.admin_shop_preview(cart);
 PERFORM pg_temp.shop_assert(preview->'issues' ? 'QUOTE_REQUIRED' AND preview->'subtotal_minor'='null'::jsonb,'quote-based service never implies a zero price');
 a:=public.admin_save_shop_service('{"unit":"hour","change_reason":"Synthetic hourly unit"}',a.id,a.version);
 rate:=public.admin_save_billing('catalog_rates','{"pricing_mode":"hourly","unit":"hour","amount_minor":2000}',(rate->>'id')::uuid,(rate->>'version')::integer,'Synthetic hourly rate');
 a:=public.admin_save_shop_service('{"quantity_step":0.25,"change_reason":"Synthetic hourly step"}',a.id,a.version);
 preview:=public.admin_shop_preview(jsonb_build_object('currency','CAD','items',jsonb_build_array(jsonb_build_object('service_id',a.id,'quantity',1.25,'hours',1.25))));
 PERFORM pg_temp.shop_assert((preview->>'subtotal_minor')::bigint=2500,'shop hourly rate uses explicit matching hours');
 PERFORM pg_temp.shop_reject(format('SELECT public.admin_shop_preview(%L)',jsonb_build_object('currency','CAD','items',jsonb_build_array(jsonb_build_object('service_id',a.id,'quantity',1.25,'hours',2)))::text),'22023','hourly quantity mismatch rejected');
 a:=public.admin_save_shop_service('{"status":"archived","change_reason":"Withdraw test"}',a.id,a.version);
 preview:=public.admin_shop_preview(cart);
 PERFORM pg_temp.shop_assert(preview->'issues' ? 'SERVICE_UNAVAILABLE','withdrawn service invalidates the cart');
 PERFORM pg_temp.shop_assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.shop_catalog()) x WHERE x->>'id' IN (a.id::text,pack.id::text)),'withdrawn member also hides its package');
 PERFORM pg_temp.shop_assert(original->'items'->0->'service'->>'status'='published' AND (original->'lines'->0->'rate'->>'amount_minor')::integer=1001,'old simulation snapshots are unchanged');
 PERFORM pg_temp.shop_assert(EXISTS(SELECT 1 FROM public.configuration_revisions WHERE record_id=a.id AND resource='services' AND actor_id=auth.uid()),'service history records actor and snapshots');
END $$;
RESET ROLE;
SET LOCAL ROLE anon;
SELECT pg_temp.shop_assert(jsonb_typeof(public.shop_catalog())='array','anonymous caller can read only public shop projection');
SELECT pg_temp.shop_assert(public.shop_catalog()::text NOT LIKE '%basis_minor%' AND public.shop_catalog()::text NOT LIKE '%percentage_bps%','public projection excludes platform fee data');
RESET ROLE;
SELECT 'ALL SHOP ASSERTIONS PASSED; FIXTURES ROLLED BACK' AS result;
ROLLBACK;
